SELECT t.date_sk, t.sales_type, SUM(t.net_profit) AS total_net_profit, SUM(t.ext_discount_amt) AS total_discount, CASE WHEN SUM(t.net_profit) > 500000 THEN 'TOP' WHEN SUM(t.net_profit) BETWEEN 200000 AND 500000 THEN 'MID' ELSE 'LOW' END AS profit_band, DENSE_RANK() OVER (ORDER BY SUM(t.net_profit) DESC) AS profit_dense_rank, SUM(SUM(t.net_profit)) OVER (ORDER BY t.date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_profit, PERCENT_RANK() OVER (ORDER BY SUM(t.net_profit) DESC) AS profit_percentile FROM (SELECT cs.cs_sold_date_sk AS date_sk, 'catalog' AS sales_type, cs.cs_net_profit AS net_profit, cs.cs_ext_discount_amt AS ext_discount_amt FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk WHERE sm.sm_type = 'AIR' UNION ALL SELECT ss.ss_sold_date_sk AS date_sk, 'store' AS sales_type, ss.ss_net_profit AS net_profit, ss.ss_ext_discount_amt AS ext_discount_amt FROM store_sales ss JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk WHERE hd.hd_income_band_sk >= 5) t GROUP BY t.date_sk, t.sales_type ORDER BY t.date_sk
